quests[40918] = { id = 40918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold Heroic Reward Quest" }
quests[40919] = { id = 40919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Bent for Leather", description = "Ah, my faithful assistant. I have just the task for you.\n\nAs you have seen, fel power permeates living tissue and can easily be coaxed out.\n\nAlso, these damned bats are driving me to my wits' end. There is an opportunity to kill two bats with one blade, it seems. Your blade.\n\nTake this crystal. It should rip those hellions from the sky and into your waiting arms.\n\nYou may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.", progress = "Have you obtained the hides?", completion = "I can no longer hear their shrieking. Finally, peace and quiet!", objectives = "Collect 50 Felbat Hide Scraps for Kyrtos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40920] = { id = 40920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebinder Bounty" }
quests[40921] = { id = 40921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Bastillax 1" }
quests[40922] = { id = 40922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Mephistos 2" }
