quests[40924] = { id = 40924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Bastillax 4" }
quests[40925] = { id = 40925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitestone Burglary" }
quests[40927] = { id = 40927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jandvik's Last Hope", description = "Commander Malt'his was conferring with a sea giant?\n\nWithout your help, this village will surely fall to the combined forces of the Sashj'tar and the sea giants.\n\n<Toryl stands there quietly for a moment.>\n\nMeet me in an underground cave out in Azuregale Bay.\n\nI want to show you something that may turn the tide in this battle.", completion = "I do not know who you are, but I must thank you.", objectives = "Meet with Toryl in the Sashj'tar Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40929] = { id = 40929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbols of Power", description = "This demon has information that could lead us to those in charge.\n\nUnfortunately, he is more fearful of his master than he is of us. We need to change his mind about that.\n\nThe most powerful Burning Legion soldiers often carry an emblem of their rank and status within the demon army.\n\nSeek out the stronger demons in Felsoul Hold, slay them, and return to me with their emblems.\n\nWe will show this wyrmtongue servant who it is he should fear...", progress = "Do you have the Legion Emblems?", completion = "I see you have returned with the emblems. Excellent.\n\nLet's see how this wyrmtongue reacts when we show him what we've made of his comrades.", objectives = "Collect 8 Legion Emblems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40930] = { id = 40930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apocalypse", description = "<The Lich King's chill voice fills your mind once again>\n\nThere is an ancient blade, lost in the echoes of time, that has the power to bring my vengeance upon the Legion. \n\nIt is known as Apocalypse.\n\nI've sensed the blade in the possession of the Dark Riders of Deadwind Pass. Their magic conceals them from my sight but they cannot hide from the scourge! They were last seen by my agents near a place called Manor Mistmantle.\n\nGo there, {name}. Defeat the Dark Riders, and claim the blade!", progress = "And just why should I help you, {class}?", completion = "I am left with little choice. I cannot face another Dark Rider ambush alone, and you are obviously formidable.\n\nI will help you find your artifact, but only if you will allow me to return the others in their possession to their rightful place.\n\nDo we have a deal, {class}?", objectives = "Start your search for Apocalypse at Manor Mistmantle in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40931] = { id = 40931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Curse", description = "Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them.\n\nThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.\n\nCome with me to Ariden's camp. I will explain on the way.", completion = "As much as your company pains me, you are proving to be a powerful ally. \n\nI believe the key to finding the Dark Riders is here somewhere. It is strange that the riders haven't followed us here, but we should make haste lest they change their mind.", objectives = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40932] = { id = 40932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. \n\nIt has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", completion = "Dark energy hums from the journal, which appears to be the writings of Ariden, and chronicles his time in Deadwind Pass. One entry in particular stands out:\n\n\"I hear the whispers. They call me from the wet soil of shallow graves, hearkening me to my legacy. \n\n\"But what legacy? The merchant I once was had no special bloodline...\n\n\"Nevertheless, I am drawn to it. The dread blade... the world-ender... Apocalypse.\"", objectives = "Search around Ariden's Camp for clues leading to the Dark Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40933] = { id = 40933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grisly Task", description = "Wet soil? Shallow graves?\n\nI think the journal is referring to the gravesites off of the lake near Karazhan. Nobody knows who is buried there, but they may be the key to finding the Dark Riders.\n\nYou can... speak to the dead, yes?", completion = "The chill down my spine tells me that you must have met with success.\n\nWhat did you find?", objectives = "Raise the dead buried in the Sodden Graves in Deadwind Pass until you find one who can point you to the Dark Riders location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40934] = { id = 40934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", progress = "Didyou find what you seek, {class}?", completion = "Today was a great blow against the Dark Riders, and a victory for the people of Duskwood. \n\nThey are in your debt, as am I.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40935] = { id = 40935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Vengeance", description = "I was wrong about you, death knight. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.\n\nNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Apocalypse, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, death knight.", completion = "The champion of the Lich King returns, and with a mighty weapon to bear against our demon foes!\n\nMay the Burning Legion tremble at the sight of our forces!", objectives = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40936] = { id = 40936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Revil Convinced" }
quests[40937] = { id = 40937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Revil Defeated" }
quests[40938] = { id = 40938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light and the Void", description = "Alonsus Faol has been a valuable ally, and his instincts about you have proven true. I believe you are uniquely suited to assist in a matter that will bring a great force of good into this world.\n\nI must take you somewhere far from Azeroth to finish a task my people began long ago. Will you aid us?", progress = "We have important work to do, {name}.", completion = "Welcome back, Cardinal. I think you'll find we've done quite a job getting this place prepared for you. We should get started immediately.", objectives = "Aid Velen with his mysterious task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40939] = { id = 40939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stormwing Matriarch" }
quests[40941] = { id = 40941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Blackrock forces at the Pit in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40942] = { id = 40942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Blackrock orcs at the Pit in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40943] = { id = 40943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei force in Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40944] = { id = 40944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces deep within Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40947] = { id = 40947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery", description = "Verene's child has gone missing. I can guess what happened, but I need to be sure.\n\nMost guardsmen use couriers to relay delicate information. In this, magic is strictly the province of high ranking officials.\n\nTake this blade. Do not touch the cutting edge. Use it to silently waylay the couriers and collect any correspondence they carry.\n\nWith any luck, the missives will tell us exactly where to find the girl.\n\nWe guards know everything, after all.\n\n<Silgryn offers you a winning smile.>", progress = "Were you successful?", completion = "Fine work. I will read these over.", objectives = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40949] = { id = 40949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Their Last Stand", description = "I've been watching you- you are not with them.\n\n<Ivanel coughs quietly.>\n\nI am not long for this world, but there is one thing I would have you do while you are here.\n\nThe hippogryphs here still fight bitterly to defend their home and their companions in the Moon Guard. They have not accepted that the Guard is no more. \n\nPlease... send them away. Let them know there is nothing left for them to fight for here.", progress = "What is it?", completion = "Thank you. I feel better knowing they will not continue to sacrifice themselves for us.", objectives = "Dissuade 5 Lingering Moonfall Hippogryphs", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40950] = { id = 40950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring Success", description = "All has gone as planned. Your new blades are a testament to that.\n\nWe will demand a great deal of you in the weeks and months to come, as we must. But we would be remiss if we failed to take a moment to celebrate a job well done.\n\nWhat do you say?", progress = "It's kill or be killed.", completion = "It seems you struck a nerve.", objectives = "Celebrate the successful acquistion of your artifact with your fellow Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40951] = { id = 40951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitestone Bazaar" }
quests[40952] = { id = 40952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter to Hunter", description = "Now that you wield Thas'dorah, it's time to learn more about the night elf who set you on this journey\n\nI suggest returning to the Hunter's Reach shop where you met my courier. Whoever this Emmarel Shadewarden is, it seems she has some part to play in the war against the Legion.", completion = "There is much to do, noble {class}. But first, I suppose you'll want to learn a little more about who I am and why I have sought you out.", objectives = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40953] = { id = 40953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Eagle's Wings", description = "Since ancient times, my order has stood vigil on these Broken Isles, watching for the Legion's return. Only a handful of us remain... but that changes today.\n\nThe artifact you hold is more than a weapon. It is a symbol that will unite hunters of all kingdoms and creeds.\n\nI'm sure you have questions. Meet me at the Trueshot Lodge in Highmountain and see with your own eyes what awaits us. Snowfeather and I will make our own way there.", completion = "I've observed your skills for some time, {name}. Watched you from a distance.\n\n\n\nWait, that sounds a little creepy. Sorry, my social skills are a tad rusty. Let me start again.\n\nOur order has been on the lookout for hunters who could lead the Unseen Path into a new era. No one is more qualified for that role than you.", objectives = "Meet Emmarel Shadewarden at Trueshot Lodge in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40954] = { id = 40954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unseen Path", description = "For a thousand years, the Unseen Path has watched and waited. We remained few in number, quietly acting behind the scenes when Azeroth needed us. Only a select few even knew our group existed.\n\nBut the time for lingering in the shadows is over.\n\nBefore we begin our work, you should hear more about the Unseen Path.", completion = "The Legion has returned, and the Unseen Path needs new blood... new leadership.\n\nThe weapon you hold is proof there is no one better suited to this task.\n\nWill you take up the mantle? Will you fulfill the oath my order took so long ago?", objectives = "Hear Emmarel's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40955] = { id = 40955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oath of Service", description = "Assembled before you are many of our world's greatest archers, rangers, beast masters, and trappers, ready to fight the Legion as one.\n\nIt is time to take your first step in becoming a true leader of hunters.\n\nWe gather at the fire pit and take our oaths of service before the statue of Ohn'ahra. Touch the statue and kneel before it while I recite the oath, and the Unseen Path will be reborn!", progress = "Ohn'ahra has blessed our order!", completion = "Ohn'ahra has not appeared to us since the order's founding!\n\nThis is surely a sign that with you guiding us, the Unseen Path will triumph over the Legion!", objectives = "Kneel before the eagle statue and pledge your service to the Unseen Path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40956] = { id = 40956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Says...", description = "It is time to establish the first secure connection in our teleportation network.\n\nTake this beacon to the Ruins of Elune'eth above us and survey the area to find a suitable location.\n\nOnce your survey is complete, place the beacon and I will anchor a connection to it from here.", completion = "<This seems like a good location for the teleporter.>", objectives = "Use the Telemancy Beacon to survey the Ruins of Elune'eth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40957] = { id = 40957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strong Right Hand", objectives = "Even with the support of your fellow hunters, the crusade against the Legion will consume much of your time and attention. It is a war you cannot fight alone.\n\nI first served our order's founder, Namuria Gladesong, acting as her eyes and ears when she was needed elsewhere. It would be my honor to do the same for you, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40958] = { id = 40958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Matters", description = "Now that your artifact is ready, it's time to plan your first strike against the Legion.\n\nSpeak to Tactician Tinderfell, our expert on such matters.", completion = "Hail, Pathfinder! It will be my honor to aid you in the fight against the Legion.", objectives = "Speak to Tactician Tinderfell in the Trueshot Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40959] = { id = 40959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Campaign Begins", description = "The Legion believes we are still reeling from our loss on the Broken Shore.\n\nLet's prove them wrong.\n\nOur scouts have mapped out the Broken Isles, learning everything we can about each region for our imminent assault.\n\nChoose where to strike first, and you will lead the Unseen Path's efforts personally.", completion = "Excellent choice. The campaign against the Legion has begun!", objectives = "Choose an initial assault point on the Command Map", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40960] = { id = 40960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luminous Pearl", description = "Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand.\n\nThis is clearly a magical item, and should be brought to a magical person.", completion = "A pearl, you say? Well now, let me have a good look at that...", objectives = "Bring the Luminous Pearl to Archmage Khadgar in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40961] = { id = 40961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dalaran Fountain", description = "You fished this up, did you? I'm... not quite sure what you want ME to do about that. Here.\n\n<Khadgar pats you on the head.>\n\n\"Good job.\"\n\nWith regard to the pearl... it does seem to be magical, but I couldn't tell you much more than that. Perhaps it might look nice in the Dalaran fountain?", completion = "She's a BEAUTY! I've never seen the like!\n\nYeah yeah, sure, throw 'er in that fountain. Light knows people throw all sorts of other junk in there.\n\n<The pearl glows brighter now, and moves to a spot above the water.>", objectives = "Bring the Luminous Pearl to the fountain in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40962] = { id = 40962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Waters", description = "Come with me to the edge of Elune'ara. Its crystal waters can wash away even the darkest shroud to reveal the truth within.", progress = "Yes, {race}?", completion = "Malfurion departed in a great hurry, but he bade me give you this before you left. Thank you for all you have done for Azeroth, and for all that you will do in time to come.", objectives = "Accompany Malfurion to Elune'ara to reveal the nature of the Remnant of Chaos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40963] = { id = 40963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Them in Claw", description = "We should have seen this coming. My sister is dead, my friends are wounded and we will likely die here.\n\nI want revenge.\n\n<Lyrea hands you a vial full of growing green liquid.>\n\nWe cannot beat them, but we can turn the Stronghold against them.\n\nWild hippogryphs are attracted to the scent in this bottle. Wild hippogryphs are also notoriously violent when the object of their attraction is not a hippogryph.\n\nUse it to clear a path deeper into the stronghold.", progress = "I thought I was alone here. Are you here to continue the fight?", completion = "I heard screams, and I was gratified that they belonged to the Nightborne. Well done.", objectives = "Attract 3 Wild Moonfall Hippogryphs to deal with the Nightborne at Moonfall Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40964] = { id = 40964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rift Between", description = "I was with Lothrius when the Nightborne poured into the stronghold.\n\nHe and his constructs managed to get the majority of us out of the Athenaeum, but he was cornered before he could make good on his own escape.\n\nI know he still lives- I feel it in my gut!- but I cannot go back for him myself. My injuries are too severe.\n\nBeakbuck will take you to where we last saw Lothrius. Simply let him know when you are ready to leave.\n\nGo quickly, and good luck!", completion = "Serena sent you? Good... she still lives.", objectives = "Locate Lothrius Mooncaller in the Athenaeum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40965] = { id = 40965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay Waste, Lay Mines", description = "They ransacked my library, {name}.\n\nIf they want our knowledge, we will give it to them. \n\nThis piece of rune work will allow you to cast an ensnaring spell on the ground. When the Nightborne cross the threshold they will see the true might of the Moon Guard.\n\nTeach them well!", progress = "How fares the education?", completion = "A lesson we all must one day learn. Never assume your enemy dead until you see their corpse. <Lothrius grins.>", objectives = "Slay 50 Nightborne With the Trap Rune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40966] = { id = 40966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualists in Our Midsts" }
quests[40967] = { id = 40967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Little Left", description = "I have not been able to leave the safety of my guardians to search, but there are three tomes of great importance to me and mine. \n\nThey contain secrets and cantrips that the Nightborne must NOT obtain. \n\n<Lothrius raises his hand to your forehead, cementing the names of three tomes into your mind> \n\nIf we cannot best them, we must preserve all we can. Hurry, {name}.", progress = "Did you locate them?", completion = "Thank the Mother Moon... They survived!", objectives = "Locate and recover \"Anthology of the Guard\", \"Magical Manifest of the Moon\", and \"Aftermath of the Well\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40968] = { id = 40968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Stolen Power", description = "My injuries will not kill me, but I cannot fight. I have my own idea of how to deal with the remaining Nightborne.\n\nThey destroyed our defense matrix as soon as they arrived. Surely one of them carries the spell focus necessary to reactivate it.\n\nFind it, then go to a hippogryph. They linger throughout the Stronghold.\n\nThese loyal beasts will take you to the skies and take care of the rest.", objectives = "Acquire a Volatile Spell Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40969] = { id = 40969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starweaver's Fate", description = "I will take these tomes to Thalrenus.\n\nThere is one thing that weighs heavily on my mind, and I would like for you to attend to it in my stead. \n\nMy wife and life partner, Syrana Starweaver, resides in the Starweaver's Sanctum across the bridge. It fell shortly after the Nightborne entered the Stronghold. \n\nIf she still lives she will need to know of our efforts. Her power is sorely needed. \n\nGive her my best- I will be along shortly.", completion = "Lothrius and Thalrenus live, then. There may be some hope yet. Thank you for braving the bridge, stranger.", objectives = "Locate Syrana Starweaver", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40970] = { id = 40970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orchestrator of Our Demise", description = "Conjurer Thalerian must be stopped.\n\nHe immediately sought out my father's private study when he arrived and he has not yet emerged. I worry that he may have found a very dangerous item.\n\nIt is called the Astromancer's Keystone. It is used to manipulate the stronghold's defenses.\n\nSuch magic was meant to protect the Moon Guard- used for any other purpose and it becomes unspeakably destructive.\n\nRetrieve the Keystone. Slay Conjurer Thalerian to get it, if you must.", progress = "Is it done?", completion = "They had no right to this power. Thank you.", objectives = "Slay Conjurer Thalerian and acquire the Astromancer's Keystone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40971] = { id = 40971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelming Distraction", description = "Do you see the Nightborne outside this room?\n\nThey hold us here, like mice in a cage. It is more convenient for them that we are pinned down while they search the Sanctum for my father's relics.\n\nMy companions and I can escape to higher ground with some help.\n\nTake this crystal. While standing on a mana focusing rune, use it to overcharge a Conjurer.\n\nTheir summons will turn on them and create an opening.\n\nUse it well, and we will meet you atop the stronghold when the way is clear.", completion = "We were able to make it here safely, thanks to you.", objectives = "Overcharge 3 Imperial Conjurers using the Inert Crystal. You must be standing on a Mana Focuser to use the crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40972] = { id = 40972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand of the Moon Guard", description = "This is all that remains of the Moon Guard.\n\nTake a good look.\n\nWe are but a shadow of our former selves, and we have the Nightborne to thank for our demise.\n\nFor now there is nothing more we can do. If we want to live, we must leave immediately.\n\nRetribution can wait.", completion = "I called them here. I will see that they are taken care of after the horrors my people put them through.", objectives = "Leave Moon Guard Stronghold with Thalrenus, Lothrius, and Syrana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40973] = { id = 40973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creating Time", description = "Thanks in large part to your substantial efforts, we have discovered the whereabouts of a powerful piece of our history. It should enable us to survive whatever else the Nightborne have to throw at us, and hopefully more.\n\nHowever, recovering it will require a great deal of our energy and focus. We will bolster the Starweaver's scrying efforts, but the slightest disruption will ruin this delicate spellwork. See that we are not disturbed.\n\nSpeak to Syrana Starweaver when you are ready to begin.", objectives = "Defend Syrana Starweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40974] = { id = 40974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latosius' Trial", description = "I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, {name}, and the might of the Moon Guard will be yours forevermore.", objectives = "Survive the Trial of Latosius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40975] = { id = 40975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluin Bribe Tracking" }
quests[40976] = { id = 40976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Warchief", description = "Tensions are running high, demon hunter. Warchief Vol'jin was gravely wounded in a disastrous assault on the Broken Shore.\n\nI suggest you offer your skills in service of the Horde before your presence is... misinterpreted.\n\nHigh Overlord Saurfang commands the city's defenses. Though wary of the Illidari, I believe he will give you a chance to prove your worth.\n\nSpeak to him and request passage into Grommash Hold.", completion = "Vol'jin's death was part of a larger plan. The Legion thrives on weakening its enemies from within. The demons will strike when their enemy is at its most vulnerable.\n\nWhatever grief the Horde's people are feeling, they can no longer afford to ignore us.\n\nOur time is now, Illidari!", objectives = "Speak to High Overlord Saurfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40978] = { id = 40978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bears Behaving Badly" }
quests[40980] = { id = 40980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boilback Plague" }
quests[40982] = { id = 40982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sight", description = "Sylvanas becoming Warchief may be problematic. In life she was a proud ranger, known to many in our ranks. But since the Scourge took her, some of her own allies do not trust the Banshee Queen.\n\nThe Legion will strike at the first hint of dissension.\n\nEven now, I sense something amiss, {name}. I fear that not all is as it seems.\n\nQuickly, use your Spectral Sight. We must know if there are foes among us!", progress = "Time is precious.", completion = "Of course the Legion would try to infiltrate this funeral. With the leaders of the Horde gathered in one place at one time, it was too tasty of a target for the demons to resist.", objectives = "Use your Spectral Sight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40983] = { id = 40983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Them", description = "It is just as we suspected, {name}! The demons thought they could take us by surprise.\n\nQuickly, to arms! Protect the Banshee Queen!", progress = "This is what we were born for.", completion = "Your warning just saved us from what might have been a catastrophic loss. Now we can unleash our vengeance upon this Legion filth.\n\nYou now have my attention, {class}... and perhaps a bit of appreciation as well.", objectives = "Protect the Warchief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40984] = { id = 40984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murkwater Naga Incursion: Highmountain" }
quests[40985] = { id = 40985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimescale Naga Incursion: Highmountain" }
quests[40986] = { id = 40986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Riders", description = "The catacombs? I've never heard of such a place. Unless, he means...\n\nThere's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. \n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", progress = "Did you find what you seek, {class}?", completion = "Though I'll admit I may not have been able to do this alone, I will not forget the transgressions that happened today.\n\nYou have what you came for, {class}. I think it is time you were on your way.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40987] = { id = 40987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Vengeance", description = "Our goals have been met, death knight, and it is time we part ways.  I think I will be glad to see the last of you.\n\nGo on, return to your dark masters. We are done here.", completion = "The champion of the Lich King returns, and with a mighty weapon to bear against our demon foes!\n\nMay the Burning Legion tremble at the sight of our forces!", objectives = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40988] = { id = 40988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Many Cooks", description = "Greetings. I am called Nomi.\n\nI couldn't help but notice that recipe that you just picked up and... well, you'd never guess it, but I'm a bit of a chef myself.\n\nUnfortunately, I'm not much of a fighter, and this place is dangerous. You, on the other hand, are clearly an accomplished {class}.\n\nCome find me in Dalaran. Maybe we can work together!", completion = "{class}! I was hoping you'd come back.\n\nHere, take a sample of some of the recipes and dishes I've been working on.", objectives = "Meet Nomi in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40989] = { id = 40989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Sous Chef", description = "{name}? Master, is that you?\n\nDon't you recognize me? It's me, Nomi! Remember, we cooked together in Pandaria? More accurately, you cooked and I learned. I was not much more than a cub back then.\n\nBoy, am I glad to see you!\n\nI'm headed back to the Dalaran kitchens. Come find me! Maybe we can work together!", completion = "Master {name}!! I knew you'd come.\n\nHere, take a sample of some of the recipes and dishes I've been working on.", objectives = "Meet Nomi in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40990] = { id = 40990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Recipe List", description = "I've tried adventuring, and it isn't for me. Cooking is my one true passion: the heat of the stove, the sizzle of bacon... nothing beats it.\n\nLet me help you, Master {name}. If you can bring me some recipes, I can work on improving them, here in Dalaran.\n\nWe'll make a great team. What do you say?", progress = "We need more recipes before we can do any meaningful work in this kitchen.", completion = "You are truly amazing, Master {name}.\n\nNow, let's get to work, shall we?", objectives = "Learn 6 Legion cooking recipes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40991] = { id = 40991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening the Test Kitchen", description = "I can cook, but I can't really hunt... or even fish, for that matter.\n\nIf you bring me ingredients, however, I will use them to research new recipes for you.\n\nWe can start with the few fish I managed to scrounge up. You'll find them in the barrel in the back of the kitchen.", progress = "Mackerel may not be extravagant, but it will fill your belly.", completion = "We've done it! With this technique, we should be able to prepare dried mackerel strips much more efficiently.\n\nI am certain that there is much more we can learn. Keep bringing me ingredients, and I will keep the oven on!", objectives = "Obtain 5 of Nomi's Silver Mackerel, then bring them to Nomi to research.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40992] = { id = 40992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Among Thieves", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40994] = { id = 40994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Tools for the Job", description = "The blades you wield are among the most powerful in all of Azeroth, but we must always remain two steps ahead of the enemy. Even now their armies grow in strength, and those weapons will make you a prime target for their assassins.\n\nSpeak with Marin Noggenfogger in the Uncrowned Vault next door. He recently completed a project which you will find most intriguing.", completion = "So, what can I do for you today, Master {name}?", objectives = "Speak to Marin Noggenfogger in the Hall of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40995] = { id = 40995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Injection of Power", description = "Power, eh? You bet! I got just the thing!\n\nWe've managed to get our hands on a rare venom from an uncharted island deep in the south seas. We captured as much of it as we could.\n\nI had my boys build a device that can inject the venom into weapons, but just in small quantities for now until we've got a better handle on its effects.\n\nAnywho, we got it locked up in a secure area just over there. You're free to use it, Shadow {name}... for a price, of course!", progress = "It's like my momma used to say - if you've got the coin, we've got a deal.", completion = "Hey, don't even mention it, pal. I'm here for ya any time you need anything!\n\nSeriously though, don't mention it. There are some folks that would do anything to get their hands on this stuff.", objectives = "Convince Marin Noggenfogger to allow you to use the Crucible of the Uncrowned, then use it to empower your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40996] = { id = 40996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegation", description = "If I might impart some advice to aid you on the trials and tribulations ahead: do not hesitate to use the many resources of the Uncrowned to aid your efforts.\n\nThere is a communal board in the tavern beyond this chamber where we organize the efforts of our underlings.\n\nSeek out Nikki by the board - she can show you the ropes.", completion = "I don't know nothin' about nobody.\n\nOh, who I am I kiddin'? I know everything about everybody! How's it goin', Shadow {name}?", objectives = "Speak to Nikki the Gossip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40997] = { id = 40997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethal Efficiency", description = "Word is you're headin' down to the Broken Isles. That true?\n\nSoon as news got out about the place, we combed through every book, tome, and paper we could get our hands on. We put together quite the report! You should take a look.\n\nWhile you're here, this board is where the magic of the Uncrowned happens. You can put a bounty on a king's head, offer a reward for felsilk cloth... just jot down your latest whim and your agents will take care of it.", completion = "Great choice! We have tons of intel on that place.", objectives = "Select your first assault point on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40998] = { id = 40998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous", description = "{class}t {name}, the recruitment operation was successful.\n\nRendezvous in the Hall of Shadows as soon as possible to debrief.", objectives = "Use your Extraction Point ability to return to the Hall of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41000] = { id = 41000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Forgalash's Burden", description = "That sea witch spoke the truth.\n\nI witnessed the Tidemistress confer with King Forgalash on several occasions.\n\nKill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise.\n\nI will meet afterwards in the center of Jandvik. I need to warm myself by its fires.", objectives = "Retrieve Forgalash's Prow from King Forgalash in Forgalash's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41001] = { id = 41001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Sashj'tar", description = "The Sashj'tar forces may have dwindled, but the Tidemistress has surrounded herself with her fiercest naga.\n\nThis is the time to strike a final crushing blow against the Sashj'tar.\n\nIf we can defeat them now, we may finally break the back of this menace and save Jandvik.", progress = "We must defeat the Sashj'tar once and for all.", completion = "We may have finally overcome this naga threat.", objectives = "Kill 12 Sashj'tar naga in the Sashj'tar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41002] = { id = 41002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weapon of the Horde", description = "It would seem I underestimated your initial value.\n\nWe will have need of your kind in the coming war. I plan to hunt these demons to the ends of Azeroth, and your kind will be the arrow I shall loose upon them.\n\nTell your Illidari within Orgrimmar to make ready to serve the Horde.\n\nBut make no mistake, your kind once served the Betrayer. Betray me, and there is no world you can run to that will save you from my vengeance.", completion = "You have proven our worth to the new Warchief. Excellent work.\n\nTo vanquish the Legion, we will need the Horde's strength at our backs.", objectives = "Report to Elthyn Da'rai at the Illidari camp in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41003] = { id = 41003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emperor's Gift", description = "Ah, Sheilun, the legendary staff wielded by our last emperor. If the Legion were to acquire this weapon, they could unleash untold horrors across the whole of the continent. They must be stopped!\n\nIf you want to get to the Terrace as fast as possible, you should hitch a ride directly to the mainland. Tak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", progress = "The Terrace of Eternal Spring is a very sacred place for mainland Pandaren. I hope you were able to preserve it from corruption. Enough of Pandaria was destroyed when Garrosh Hellscream turned it into a battlefield.", completion = "Incredible. The very staff the Emperor used to cloak Pandaria in mists all those ages ago!\n\nTreat that staff well, {name}. It will save your life. And probably the lives of all your friends, as well...", objectives = "Retrieve Sheilun, Staff of the Mists, from the Terrace of Eternal Spring. See Tak-Tak to fly directly to the Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41006] = { id = 41006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassinate That Guy" }
quests[41008] = { id = 41008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter to Hunter", description = "I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey.\n\nI can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness.\n\nFight well, {name}. May Talonclaw serve you well.", sourceObjective = "Return to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41009] = { id = 41009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter to Hunter", description = "Now that Titanstrike is yours, ye should learn more about the night elf who set us on this journey.\n\nShe might well be back at the Hunter's Reach shop where you met her. Whoever this Emmarel Shadewarden is, I'd bet me beard she has some part to play in the war against the Legion!\n\nThanks again fer the fun, {name}. If ye ever have need of me, just call!", completion = "There is much to do, noble {class}. But first, I suppose you'll want to learn a little more about who I am and why I have sought you out.", objectives = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41010] = { id = 41010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Frenzy", description = "{name}!\n\n<pant, pant>\n\nYou've got to see it! The fish, they're... they're everywhere!\n\nOff the coast of Val'sharah, something's whipping them up into a frenzy.\n\nI've never seen better fishing in my life!\n\nI've got a boat down below. Grab your pole and I'll take you there!", completion = "What in the world have you brought me?! Nat told you to ask me to turn THIS into a pole?\n\n<Marcia takes the severed lure from you. As she holds it close to the pearl, it begins to resonate with it.>\n\nThat's interesting. There seems to be a connection between this and the pearl. Maybe turning this into a fishing rod can yield some interesting results...", objectives = "Follow Nat Pagle to the Gloaming Reef, then dispatch all of the fish in the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41011] = { id = 41011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbralshard Rituals" }
quests[41012] = { id = 41012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirin Tor Showdown Seen" }
quests[41013] = { id = 41013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkbrul Arena" }
quests[41014] = { id = 41014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Road" }
quests[41015] = { id = 41015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts Need Artificers", description = "Your weapon is indeed powerful, but we shouldn't rest on our laurels. I've managed to procure one of the dwarves' foremost experts on artifice and enchanting.\n\nI'd like you to speak with Betild and see if she can't infuse the weapon with even greater potency.", completion = "Ach, there ye are. Let me see that priceless weapon ye're swingin' 'round like a stick ye bought at the gift shop!", objectives = "Speak with Betild Deepanvil in Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41016] = { id = 41016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BC TL" }
quests[41017] = { id = 41017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowering Your Artifact", description = "Since ye're bound an' determined ta crack that thing against every demon on Azeroth, let's see if we can't squeeze what we can out of it. With Saa'ra's power I've reworked this 'ere draenei altar into somethin' ye can use to focus... eh, let's skip that part, shall we?\n\nJust stick the thing in there and give it a whirl!", completion = "Well ain't that nice an' shiny!\n\nYou'll need ta get used to usin' that thing. Then we can mess with it rather than, ye know, puttin' it in a museum and respectin' it for the piece o' history that it is.\n\n You should head back to Alonsus, he's giving us the eye.", objectives = "Use the Altar of Light and Shadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41019] = { id = 41019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Actions on Azeroth", description = "Let me show you the Command Map. Thanks to some draenei construction and naaru magic we now have a window into the Broken Isles! You can devise strategy, send your agents on missions, and choose our first area to operate in.\n\nTake a look and let me know where we are going!", completion = "An excellent choice! We will do our best to support your efforts on the Broken Isles.", objectives = "Use the Command Map to select your order's first operational area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41024] = { id = 41024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirge of the Dead" }
quests[41025] = { id = 41025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Fallen" }
quests[41026] = { id = 41026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Shadows" }
quests[41027] = { id = 41027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Breath", description = "<The parchment is soaked in seawater. A note is hastily scribbled on it.>\n\nTo whomever finds this note first,\n\nBefore I was cast from Suramar, I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne.\n\nAll of this was forgotten when the Legion came.\n\nBefore I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea.\n\nDrink it and explore the vast deep in my honor.You will learn:", sourceObjective = "Drink the Nightfallen Alchemist's Strange Draught in Azuregale Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[41028] = { id = 41028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Grid", description = "This station has fallen into disrepair. The circuit is broken, and to mend it we must recharge the seals in the central chamber.\n\nBoth a high potency current and low potency current are needed for each seal. Direct the currents to point at the same seal, then engage the seal.\n\nMe? I shall supervise. You are the help, after all.", completion = "I must admit I am impressed. You may actually be of some use to us.", objectives = "Charge the Moon Seal, Star Seal, Beast Seal and Elven Seal in Ley Station: Tel'Anor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41029] = { id = 41029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest for Latosius Challenge 2" }
quests[41030] = { id = 41030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil Reclamation", description = "The smooth square sigil weighs a fair amount more than its appearance would suggest. \n\nHandling it results in an intense tingling sensation in your palm- this is an object of focused, pure power. \n\nSuch an advantage should not be so easily surrendered to the Nightborne.", progress = "What is this?", completion = "You were wise to keep these out of our enemies' hands, {class}. I believe you can be trusted.", objectives = "Collect 7 Moon Guard Sigils.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41031] = { id = 41031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the People", description = "We have a problem, friend.\n\nAcross the canal is a district not well known for affluence. Since the demons' arrival, it has been locked down. I have heard the cries of those who have been deprived of sustenance.\n\nTake this wineskin. Find an Arcwine fountain and take your fill.\n\nFind those who are suffering and offer them a drink. It is the best we can do in the present circumstances.\n\nYou must not be seen doing this, {name}. It will end badly.", objectives = "Locate an Arcwine Fountain to fill your Empty Arcwine Skin, then offer Arcwine to Mana-Starved Nightborne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41032] = { id = 41032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Spell Seekers", description = "The Nightborne are here in force. As if that were not worrying enough, they now bring reinforcements.\n\nI have seen them opening large portals to Suramar.\n\nThrough these portals they have called in their constructs. They are immune to much of my magic and so represent something of a stumbling block to rejoining the others.\n\nFind the portals and close as many as you can. That should buy us some time.", progress = "I can still sense them, {name}.", completion = "Yes! I can feel their spells receding. Soon I will be able to rejoin Thalrenus!", objectives = "Close 3 Spell Seeker Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41033] = { id = 41033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", completion = "This place is built for war - it's exactly what we need to level the playing field.", objectives = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41034] = { id = 41034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Waters", description = "There is no place that the Sashj'tar can hide from you now, {name}.\n\nThey will not be expecting a direct attack in their waters. This is a perfect opportunity to cut down their commanders.\n\nMeet me in Jandvik after you have slaughtered them.", completion = "There are sea giants in the bay!?\n\nYou must tell Toryl about this grave news right away.", objectives = "Slay Raz'jira, Malt'his, and Kel'tariss in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41035] = { id = 41035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felstorm's Plea", description = "You may not know me, but I need your help, {name}.\n\nMeet me in the Violet Gate and I'll explain everything. \n\nMake haste. I fear we have little time.", completion = "I was a fool. I thought that I could banish Kathra'natir once and for all, but instead the dreadlord broke free.\n\nIn the years he spent trapped within my body, he must have been privy to my secrets... such as those of the Council of Tirisfal.\n\nThe damage he could do with this knowledge is unthinkable. He must be stopped.", objectives = "Meet Meryl Felstorm in the Violet Gate in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41036] = { id = 41036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadlord's Prize", description = "Kathra'natir escaped my grasp, but I know what his next step will be.\n\nHe seeks an ancient relic called the Forge of the Guardian, used for centuries by the Council of Tirisfal to infuse their power into the Guardian. The forge was hidden away, its location known only to the Council themselves.\n\nNow the dreadlord has this knowledge.\n\nWe must go to the Violet Hold. I only hope we are not too late.", progress = "We must hurry!", completion = "In times past, the Council of Tirisfal called upon the Tirisgarde, the protectors of Dalaran, to do battle in the Guardian's absence.\n\nIt is clear now that the hall of the Tirisgarde must be rebuilt to face this new threat.\n\nI need your help to accomplish this. First of all, you'll need to know how to get to this hall. I will show you.", objectives = "Defeat Kathra'natir in Violet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41037] = { id = 41037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", progress = "Yes?", completion = "The Fel Hammer is fully operational.", objectives = "Activate the Fel Hammer and rally your Illidari forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41038] = { id = 41038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mead Master", description = "The Storm Brew is created by a legendary vrykul brewmaster named Melba. Here is the location of her meadery along the northern Stormheim coast.\n\nIf we can convince her to share her secret recipe with us, we will gain a significant advantage over the enemy.\n\nGrandmaster, how are your skills of persuasion?", progress = "What do you seek?", completion = "My master was loved by many, and she passed her knowledge to me.\n\nHowever, the recipe for Storm Brew, her most fiercely guarded secret, was stolen before she could teach it to me.", objectives = "Speak to Aegira in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41039] = { id = 41039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Knowledge", description = "Morjirn, the head brewer of the Tideskorn clan, has the Storm Brew recipe.\n\nI have never been strong enough to assault his fortress alone, but together with you, I think we can claim retribution for my fallen master. I would like nothing better than to pry the recipe from Morjirn's cold, dead fingers.\n\nWhile we are there, we will sample his Storm Brew. I'd like to see if his brewing skills are even near my master's.", progress = "Do you have the recipe?", completion = "The last time I saw these notes, I was still a young child.\n\nI understand much of what is written here now.\n\nIt won't be easy to acquire everything here, but I believe we can do it, {name}.", objectives = "Taste the Sour Storm Brew, Weak Storm Brew, Blazing Storm Brew, and kill Morjirn for the Storm Brew Recipe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41040] = { id = 41040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Brewmaster", description = "I've made a new breakthrough with Melba's Storm Brew recipe.\n\nWe need the use of a special cauldron, one owned by Odyn himself.\n\nThis cauldron is located in none other than the Halls of Valor.\n\nThere is only one way to enter this exalted place, and that is through the storm god's favor.\n\nYou must find a way to enter the hall of warriors. You may require allies for this endeavor, {name}.", completion = "Hello, champion.\n\nI have been watching you from afar.", objectives = "Speak to Melba in the Halls of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41041] = { id = 41041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sashj'tar Allies DISBALED", description = "Commander Malt'his was conferring with a sea giant?\n\nWe are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik.\n\nYou must tell Toryl about this grave news right away.", sourceObjective = "Speak with Toryl in Jandvik.", sourceObjectiveStatus = "unverified-source-field" }
quests[41042] = { id = 41042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Chomper" }
quests[41045] = { id = 41045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matron Moves" }
quests[41047] = { id = 41047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infused with Power", description = "The weapon you hold will strike a potent blow against the Legion... but the demons are relentless. Just as your battle tactics grow and evolve, so must your weapon.\n\nThe altar before you courses with ancient magic, and is alive with the skill and dedication of the hunters who have used it through the ages.\n\nPlace your artifact upon it, and over time you will awaken the full potential of your weapon.", completion = "Wondrous! The growing power of your artifact will strike fear into the hearts of the demon army!", objectives = "Use the altar to imbue your artifact weapon with a new power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41048] = { id = 41048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 003 - Jandvik - twh" }
