quests[41052] = { id = 41052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Plea", description = "{name}, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard.\n\nI fear he is determined to return to the Broken Shore. Will you speak to him?", progress = "Will you help?", completion = "Very well, let us see what awaits us on that ill-fated shore.\n\nAt the very least, a lot of dead demons! Hah!", objectives = "Meet with High Overlord Saurfang at Krasus' Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
